// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    Succeeder s;
    function setUp() public { c = new Proxy(); s = new Succeeder(); }
    function testFuzz_property(bytes memory data) public {
        bool ok;
        try c.forward(address(s), data) { ok = true; } catch { ok = false; }
        assertTrue(ok, "forward must succeed when callee call succeeds");
    }
}

contract Succeeder {
    fallback() external payable {}
}
